#!/bin/bash

# Configuration
SESSION_ID="${1:-e9f63772-cec8-4ea6-a218-f9f7d476f170}"
MESSAGE_CONTENT="${2:-Hello, how are you doing today?}"
TOKEN="${3:-eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..vH-QXjs6JpGHIoPGI2s9YaF7MiA0rwHYx6U8CZOM1XQ}"
API_URL="http://localhost:8000/api/cart/chat/${SESSION_ID}/messages"

echo "==== SEND CHAT MESSAGE ===="
echo "Session ID: ${SESSION_ID}"
echo "Message: ${MESSAGE_CONTENT}"

# Create JSON payload using single quotes to avoid shell interpretation issues
JSON_PAYLOAD='{"content":"'"${MESSAGE_CONTENT}"'","messageType":"text"}'

echo "Payload: ${JSON_PAYLOAD}"
echo "Sending message..."

# Send the message
curl -s -X POST "${API_URL}" \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer ${TOKEN}" \
  -d "${JSON_PAYLOAD}"

echo ""
echo "Message sent!" 